It will be convenient to divide the major arcs $\mathfrak{M}$ into three disjoint subsets:  egin{align} \mathfrak{M}=\mathfrak{M}_1\cup\mathfrak{M}_2\cup \mathfrak{M}_3, \end{align} where  egin{align} 
otag \mathfrak{M}_1 = igg\{t& \in [0, X)\cap \mathbb{Z}:  igg\lvert\dfrac{t}{X}-\dfrac{a}{q} iggvert \leq \dfrac{(\log X)^C}{X}~	ext{for some}\, (a, q)=1, 1\leq a <q\leq (\log X)^C, q
mid X igg\},\ 
otag \mathfrak{M}_2= igg\{t& \in [0, X)\cap \mathbb{Z}: \dfrac{t}{X}=\dfrac{a}{q}+ \dfrac{\eta}{X}\ 
otag & 	ext{for some}\, (a, q)=1, 0\leq a< q\leq (\log X)^C, q\geq 1, q\vert X, 0<\lvert \eta vert \leq (\log X)^C igg\},\ 
otag \mathfrak{M}_3 = igg\{t& \in [0, X)\cap \mathbb{Z}: \dfrac{t}{X}=\dfrac{a}{q}\: 	ext{for some}\, (a, q)=1, 0\leq a< q\leq (\log X)^C, q\geq 1, q\lvert X igg\}. \end{align}

Let $z\in [2, X]$ be a parameter to be chosen later. We let  egin{align} 
otag \mathcal{P}_3=\{p\equiv 3\imod 4, p 
mid b\} \quad 	ext{and} \quad P_3(z) = \prod_{\substack{p\leq z\p\in \mathcal{P}_3}}p. \end{align} Then, we have  egin{align} \sum_{\substack{p<X\p\equiv r\imod b}}1_{\mathcal{A}}(p) 1_{\mathbb{B}}(p-1) &\leq \sum_{\substack{p<X\(p-1, P_3(z))=1}}1_{\mathcal{A}_r}(p)\ 
otag &< \dfrac{10}{9\log X}\sum_{\substack{X^{9/10}<p<X\(p-1, P_3(z))=1}}1_{\mathcal{A}_r}(p)\log p + X^{9/10}\ &< \dfrac{10}{9\log X}\sum_{\substack{n<X\(n-1, P_3(z))=1}}\Lambda(n)1_{\mathcal{A}_r}(n) + X^{9/10}. \end{align} Next, for $d|P_3(z)$, we set  egin{align} 
otag {E}(d)=\sum_{\substack{n<X\n\equiv 1\imod d\}}\Lambda(n)1_{\mathcal{A}_r}(n)- \dfrac{1}{\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n). \end{align} Therefore, by Theorem ef{Main Theorem} with $D=X^{3/10}$, for any large real number $A>0$, we find that  egin{align} 
otag \sum_{\substack{d\leq X^{3/10}\d|P_3(z)}}\lvert {E}(d)vert \ll \dfrac{X^{\zeta}}{(\log X)^A}. \end{align} Now, we choose $c(n)=\Lambda(n)1_{\mathcal{A}_r}(n)$ for $n<X$ and $z_1=D=z=X^{3/10}$ in Lemma ef{fundsemi}. Clearly, the sequence $c(n)$ satisfies the axioms of sieve theory with $\mathfrak{g}(d)=d/\varphi(d)$ and $\varkappa =1/2$. Therefore, by the upper bound semi-linear sieve \eqref{upper} with $u_1=1$, we have  egin{align} 
otag \sum_{\substack{n<X\(n-1, P_3(z))=1}}\Lambda(n)1_{\mathcal{A}_r}(n)\leq&~ igg(\dfrac{2e^{\gamma/2}}{\pi^{1/2}} + o(1) igg) \dfrac{b}{\varphi(b)}\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n)\prod_{\substack{p<z\p\in \mathcal{P}_3}} igg(1-\dfrac{1}{p-1} igg)+ O igg(\dfrac{X^{\zeta}}{(\log X)^A} igg), \end{align} where $\gamma$ is the Euler-Mascheroni constant. The above estimate together with the estimates from \eqref{upper1} and \eqref{upper2} allows us to obtain  egin{align} 
otag \sum_{\substack{p<X\p\equiv r\imod b}}1_{\mathcal{A}}(p)1_{\mathbb{B}}(p-1) \leq &~ igg(\dfrac{2e^{\gamma/2}}{\pi^{1/2}} + o(1) igg) \dfrac{10b}{9\varphi(b)\log X}\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n)\prod_{\substack{p<z\p\in \mathcal{P}_3}} igg(1-\dfrac{1}{p-1} igg)\ 
otag &+ O igg(\dfrac{X^{\zeta}}{(\log X)^A} + X^{9/10} igg). \end{align} We can now use Mertens' estimate \cite[Theorem 3.4(c)]{kou} to the product over the primes (for example, see \cite[p.278]{opera} for a detailed estimate) and the fact that $\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n)=X^\zeta/(b-1)$ to deduce that  egin{align} 
otag \sum_{\substack{p<X\p\equiv r\imod b}}1_{\mathcal{A}}(p) 1_{\mathbb{B}}(p-1) \ll_{b} \dfrac{X^{\zeta}}{(\log X)^{3/2}} \end{align} as desired.

From \eqref{sieve lower}, \eqref{Buch}, \eqref{EqS1} and \eqref{EqT1}, we have  egin{align} 
otag \sum_{\substack{p<X\p\equiv r\imod b}}1_{\mathcal{A}}(p)1_{\mathbb{B}}(p-1)\geq &~S(\mathcal{F}, \mathcal{P}_3, \sqrt{X})\ 
otag =&~S(\mathcal{F}, \mathcal{P}_3, X^{1/\alpha})-T\ 
otag \geq&~\dfrac{\mathfrak{S} + o(1)}{(\log X)^{3/2}}\dfrac{b}{\varphi(b)}\prod_{\substack{p|b\p\equiv 3\imod 4}} igg(1-\dfrac{1}{p-1} igg)^{-1}\ 
otag &	imes \Big(I_{	extup{sem}}(ho_{	extup{sem}}, \alpha)-\dfrac{10}{9}\cdot I_{	extup{lin}}(ho_{	extup{lin}}, \alpha)+o(1)\Big)\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n). \end{align} A simple numerical computation yields that  egin{align} 
otag I_{	extup{sem}}(ho_{	extup{sem}}, \alpha)-\dfrac{10}{9}\cdot I_{	extup{lin}}(ho_{	extup{lin}}, \alpha)>1.60492-1.4566=0.1482 > 0 \end{align} for $ho_{	extup{sem}}=3(1-4\delta)/7-\varepsilon$, $ho_{	extup{lin}}=1/2-2\delta-\varepsilon$, $\alpha=(1/3-2\delta)^{-1} +\varepsilon$, $\delta=1/1000$ with $\varepsilon>0$ small. Hence, we obtain  egin{align} 
otag \sum_{\substack{p<X\p\equiv r\imod b}}1_{\mathcal{A}}(p)1_{\mathbb{B}}(p-1)\gg \dfrac{X^{\zeta}}{(\log X)^{3/2}}. \end{align} This establishes the lower bound in Theorem ef{Main TheoremApp}. Along with Proposition ef{PropUpper}, this completes the proof of Theorem ef{Main TheoremApp}.

From \eqref{sieve lower}, \eqref{Buch}, \eqref{EqS1} and \eqref{EqT1}, we have  egin{align} 
otag \sum_{\substack{p<X\p\equiv r\imod b}}1_{\mathcal{A}}(p)1_{\mathbb{B}}(p-1)\geq &~S(\mathcal{F}, \mathcal{P}_3, \sqrt{X})\ 
otag =&~S(\mathcal{F}, \mathcal{P}_3, X^{1/\alpha})-T\ 
otag \geq&~\dfrac{\mathfrak{S} + o(1)}{(\log X)^{3/2}}\dfrac{b}{\varphi(b)}\prod_{\substack{p|b\p\equiv 3\imod 4}} igg(1-\dfrac{1}{p-1} igg)^{-1}\ 
otag &	imes \Big(I_{	extup{sem}}(ho_{	extup{sem}}, \alpha)-\dfrac{10}{9}\cdot I_{	extup{lin}}(ho_{	extup{lin}}, \alpha)+o(1)\Big)\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n). \end{align}

We have  egin{align} S\geq \dfrac{1}{\log X}\sum_{\substack{p<X\(p-1,\: P_3(X^{1/\alpha}))=1\p\equiv 3\imod 8}}1_{\mathcal{A}_r}(p)\log p. \end{align} Next, for $d|P_3(X^{1/\alpha})=\prod_{p<X^{1/\alpha},\: p\in \mathcal{P}_3}p$, where $\mathcal{P}_3=\{p\equiv 3\imod 4: p
mid b\}$, let  egin{align} 
otag {E}_1(d)=\sum_{\substack{p<X\p\equiv 1\imod {d}\p\equiv 3\imod 8}}1_{\mathcal{A}_r}(p)\log p-\dfrac{1}{4\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{n<X}1_{\mathcal{A}_r}(n). \end{align} Now we choose $c(n)=1_{\mathcal{A}_r\cap \mathbb{P}}(n)\log n$ for $n<X$ and $n\equiv 3\imod 8$ in Lemma ef{fundsemi}. Then, for $1\leq u_1\leq 3$, the lower bound semi-linear sieve \eqref{lower} yields  egin{align} 
otag \sum_{\substack{p<X\(p-1,\: P_3(X^{1/\alpha}))=1\p\equiv 3\imod 8}}1_{\mathcal{A}_r}(p)\log p \geq \dfrac{1}{4}\Big(f_{	extup{sem}}(u)+o(1)\Big)V_{	extup{sem}}(X^{1/\alpha})\dfrac{b}{\varphi(b)}\sum_{n<X}1_{\mathcal{A}_r}(n)\ + \sum_{\substack{d\leq X^{u_1/\alpha}\(d, 2b)=1}}\lambda^-_{	extup{sem}}(d){E}_1(d), \end{align} where $\lambda^-_{	extup{sem}}$ are the lower bound semi-linear sieve weights with sifting parameter $z_1=X^{1/\alpha}$, $f_{	extup{sem}}(u_1)$ is given by \eqref{fsem}, and  egin{align} V_{	extup{sem}}(X^{1/\alpha})=\prod_{\substack{p<X^{1/\alpha}\p\equiv 3\imod 4\(p,b)=1}} igg(1-\dfrac{1}{\varphi(p)} igg). \end{align} We have $z_1=X^{1/\alpha}\leq X^{1/3-2\delta-2\varepsilon^2}$, so that we can take $u_1=ho_{	extup{sem}} \alpha$, where $ho_{	extup{sem}}= rac{3}{7}(1-4\delta)-\varepsilon$ in Theorem ef{Hyp1}. We can then use Theorem ef{Hyp1} and the fact that the contribution of prime powers is negligible to bound the error term $E_1(d)$. In fact, using Chebyshev's estimate \cite[Theorem 2.4]{kou}, the contribution of prime powers can be bounded by \[\ll \sum_{d\leq X^{ rac{3}{7}(1-4\delta)-\varepsilon}}\sum_{\substack{p^m<X\ p\equiv 1\imod d\ p\equiv 3\imod 8\ m\geq 2}}1_{\mathcal{A}_r}(p)\log p \ll (\log X)\sum_{d\leq X^{ rac{3}{7}(1-4\delta)-\varepsilon}}\sum_{p\leq X^{1/2}}1 \ll X^{13/14-12\delta/7},\] which is admissible. Hence, the error term in \eqref{semi1} can be bounded as  egin{align} \sum_{\substack{d\leq X^{ho_{	extup{sem}}}\(d, 2b)=1}}\lambda^-_{	extup{sem}}(d){E}_1(d) \ll_{A, b, \delta, \varepsilon} \dfrac{X^{\zeta}}{(\log X)^A}. \end{align} Next, we simplify the main term in \eqref{semi1} using Lemma ef{Aux1}, so that  egin{align} V_{	extup{sem}}(X^{1/\alpha}) = (1+o(1))\prod_{\substack{p|b\p\equiv 3\imod 4}} igg(1-\dfrac{1}{p-1} igg)^{-1}\cdot 2C_2C_3\cdot  igg(\dfrac{\alpha \pi e^{-\gamma}}{\log X} igg)^{1/2}, \end{align} where  egin{align} C_2 =\dfrac{1}{2\sqrt{2}}\prod_{p\equiv 3\imod 4} igg(1-\dfrac{1}{p^2} igg)^{1/2}\quad 	ext{and} \quad C_3 = \prod_{p\equiv 3\imod 4} igg(1-\dfrac{1}{(p-1)^2} igg). \end{align} Putting the estimates from \eqref{semi1}, \eqref{semierr} and \eqref{Vx} in \eqref{semi0}, and noting that $u_1=\alphaho_{	extup{sem}}$, we have  egin{align} 
otag S \geq &~\dfrac{2C_2C_3(1+o(1))}{4(\log X)^{3/2}} \prod_{\substack{p|b\p\equiv 3\imod 4}} igg(1-\dfrac{1}{p-1} igg)^{-1} igg(\dfrac{\alpha}{u_1} igg)^{1/2} \int_{1}^{u_1}\dfrac{	ext{d}y}{\sqrt{y(y-1)}}\ 
otag &	imes \dfrac{b}{\varphi(b)}\sum_{n<X}1_{\mathcal{A}_r}(n)\ 
otag = &~\dfrac{C_2C_3(1 + o(1))}{2(\log X)^{3/2}}\prod_{\substack{p|b\p\equiv 3\imod 4}} igg(1-\dfrac{1}{p-1} igg)^{-1}\dfrac{b}{\varphi(b)}\sum_{n<X}1_{\mathcal{A}_r}(n)I_{	extup{sem}}(ho_{	extup{sem}}, \alpha), \end{align} where $I_{	extup{sem}}(ho_{	extup{sem}}, \alpha)$ is given by \eqref{eq: isem} Therefore,  egin{align} S\geq \dfrac{\mathfrak{S} + o(1)}{(\log X)^{3/2}}\dfrac{b}{\varphi(b)}\prod_{\substack{p|b\p\equiv 3\imod 4}} igg(1-\dfrac{1}{p-1} igg)^{-1}I_{	extup{sem}}(ho_{	extup{sem}}, \alpha)\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n), \end{align} where  egin{align} \mathfrak{S}=\dfrac{C_2C_3}{2}=\dfrac{1}{4\sqrt{2}}\prod_{p\equiv 3\imod 4} igg(1-\dfrac{1}{p^2} igg)^{1/2}\prod_{p\equiv 3\imod 4} igg(1-\dfrac{1}{(p-1)^2} igg). \end{align} This completes the proof of Proposition ef{PropAppS}.

Next, for $d|P_3(X^{1/\alpha})=\prod_{p<X^{1/\alpha},\: p\in \mathcal{P}_3}p$, where $\mathcal{P}_3=\{p\equiv 3\imod 4: p
mid b\}$, let  egin{align} 
otag {E}_1(d)=\sum_{\substack{p<X\p\equiv 1\imod {d}\p\equiv 3\imod 8}}1_{\mathcal{A}_r}(p)\log p-\dfrac{1}{4\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{n<X}1_{\mathcal{A}_r}(n). \end{align} Now we choose $c(n)=1_{\mathcal{A}_r\cap \mathbb{P}}(n)\log n$ for $n<X$ and $n\equiv 3\imod 8$ in Lemma ef{fundsemi}. Then, for $1\leq u_1\leq 3$, the lower bound semi-linear sieve \eqref{lower} yields  egin{align} 
otag \sum_{\substack{p<X\(p-1,\: P_3(X^{1/\alpha}))=1\p\equiv 3\imod 8}}1_{\mathcal{A}_r}(p)\log p \geq \dfrac{1}{4}\Big(f_{	extup{sem}}(u)+o(1)\Big)V_{	extup{sem}}(X^{1/\alpha})\dfrac{b}{\varphi(b)}\sum_{n<X}1_{\mathcal{A}_r}(n)\ + \sum_{\substack{d\leq X^{u_1/\alpha}\(d, 2b)=1}}\lambda^-_{	extup{sem}}(d){E}_1(d), \end{align} where $\lambda^-_{	extup{sem}}$ are the lower bound semi-linear sieve weights with sifting parameter $z_1=X^{1/\alpha}$, $f_{	extup{sem}}(u_1)$ is given by \eqref{fsem}, and  egin{align} V_{	extup{sem}}(X^{1/\alpha})=\prod_{\substack{p<X^{1/\alpha}\p\equiv 3\imod 4\(p,b)=1}} igg(1-\dfrac{1}{\varphi(p)} igg). \end{align}

As in the proof of Proposition ef{PropUpper}, we first split the range of $p_2$ to obtain  egin{align} 
otag \sideset{}{^ lat}\sum_{\substack{p_2< X/2\ell}}1_{\mathcal{A}_r}(2\ell p_2 +1) \leq &~\dfrac{10}{9\log (X/\ell)}\sum_{\substack{n< X/2\ell\\ell n\equiv 1\imod 4\ (2\ell n + 1, P_{\ell}(X^{1/
u}))=1}}\Lambda(n)1_{\mathcal{A}_r}(2\ell n +1)\ 
otag &+ \sideset{}{^ lat}\sum_{\substack{p_2\leq (X/\ell)^{9/10}}}1_{\mathcal{A}_r}(2\ell p_2 +1). \end{align}

Next, for $d|\prod_{p<z,\: p\in \mathcal{P}(\ell)}p$, where $\mathcal{P}(\ell)=\{p:p
mid 2b\ell\}$, we let  egin{align} 
otag {E}_2(d)=\sum_{\substack{n< X/2\ell\ 2 \ell n+1\equiv 0\imod {d}\ \ell n\equiv 1\imod 4}}\Lambda(n)1_{\mathcal{A}_r}(2\ell n+1)-\dfrac{1}{4\varphi(d)}\dfrac{b}{\varphi(b)}\dfrac{1}{\ell}\sum_{n<X}1_{\mathcal{A}_r}(n). \end{align} We now apply Lemma ef{fundlin} with the sequence $c(n) = \Lambda(n)1_{\mathcal{A}_r}(2\ell n +1)$ for $n<X/2\ell$ and $\ell n\equiv 1\imod 4$. Then given a parameter $u_2\in[1, 3]$ to be chosen later, the upper bound linear sieve \eqref{upperl} yields  egin{align}  egin{aligned} \sideset{}{^{ lat lat}}\sum_{\substack{n< X/2\ell}}\Lambda(n)1_{\mathcal{A}_r}(2\ell n +1)\leq \dfrac{b}{4\varphi(b)} ig(F_{	extup{lin}}(u_2)+o(1) ig) &V_{	extup{lin}}(X^{1/
u}) \dfrac{1}{\ell}\sum_{n<X}1_{\mathcal{A}_r}(n)\ &+ \sum_{\substack{d\leq X^{u_2/
u}\(d,2\ell b)=1}}\lambda^+_{	extup{lin}}(d){E}_2(d), \end{aligned} \end{align} where $\lambda^+_{	extup{lin}}$ are the upper bound linear sieve weights with sifting parameter $z_2=X^{1/
u}, F_{	extup{lin}}(u_2)=2e^\gamma/u_2$ and  egin{align} 
otag V_{	extup{lin}}(X^{1/
u}) = \prod_{\substack{p< X^{1/
u}\ (p, 2\ell b)=1}} igg(1-\dfrac{1}{\varphi(p)} igg). \end{align}

Let $\mathcal{S}_{	extup{Type I}}$ be the sum that we wish to estimate. Applying partial summation and then using the fact that $\sum_{n\leq y}e(nt) \ll \min(y, \|t\|^{-1})$ for any real numbers $y>1$ and $t$, we have  egin{align} 
otag \sum_{\substack{n< X/m\n\equiv c\overline{m}\imod {d}}}(\log n)^ve(mn	heta) &\ll (\log X/m)^v \min igg(\dfrac{X}{dm} + 1, \dfrac{1}{\|dm	heta\|} igg). \end{align} This implies that  egin{align} 
otag |\mathcal{S}_{	extup{Type I}}|&\ll(\log X)^{v} \sum_{d\leq D}\uptau_{h_3}(d)\sum_{\substack{m\leq M}}|{\alpha}(m)|\min igg(\dfrac{X}{dm} + 1, \dfrac{1}{\lVert dm	hetaVert} igg), \end{align} Next, we write $d^\prime =dm$, so that $d^\prime \leq DM$. Then, by the Cauchy-Schwarz inequality and Corollary ef{Corollary1} along with the fact that $|{\alpha}| \leq \uptau_{h_1}\cdot \log^{h_2}$, we have  egin{align} 
otag |\mathcal{S}_{	extup{Type I}}| & \ll(\log X)^{v+h_2} igg(X\sum_{d^\prime \leq DM}\dfrac{\uptau_{h_1+h_3}(d^\prime)^2}{d^\prime} igg)^{1/2}\cdot  igg(\sum_{d^\prime \leq DM}\min igg(\dfrac{X}{d^\prime} + 1, \dfrac{1}{\lVert d^\prime 	hetaVert} igg) igg)^{1/2}\ 
otag & \ll (\log X)^{v+h_2} X(\log X)^{(h_1+h_3)^2/2} igg(\dfrac{DM}{X}+ \dfrac{qH}{X} + \dfrac{1}{qH} igg)^{1/2}(\log X), \end{align} where we have used the fact that $\sum_{n\leq y}\uptau_h(n)^2/n \ll (\log y)^{h^2}$ for any real number $y\geq 2$ and for any integer $h\geq 1$. The above estimate on simplification yields the desired result.

The proof of the lemma is closely related to the proofs of \cite[Proposition 9]{Mat} and \cite[Theorem (p.~352)]{Mik}, but for the convenience of the reader we include the proof here. We will estimate the sum:  egin{align}
otag \mathcal{S}_{	ext{Type II}}:=\mathop{\sum\sum}_{\substack{d_1\sim D_1\d_2\sim D_2\(cd_1,d_2)=1}}\uptau_{h_1}(d_1)\max_{(c', d_1)=1}&\Bigg\lvert\sum_{\substack{mn <X\m\sim M, n\sim N\mn\equiv c'\imod {d_1}\mn\equiv c\imod {d_2}}}{\alpha}_1(m){\alpha}_2(n)e(mn	heta)\Biggvert. \end{align} Let us assume that the maximum over $c'$ is attained at $c_{d_1}$. Let ${\lambda}(d_1, d_2)\in \mathbb{C}$ be of absolute value $1$ whenever $c'=c_{d_1}$ and $(d_1, c_{d_1})=(d_1, d_2)=(d_2, c)=1$ for $d_1\sim D_1$ and $d_2\sim D_2$. Then, we have  egin{align} 
otag \mathcal{S}_{	ext{Type II}}=\sum_{d_1\sim D_1}\uptau_{h_1}(d_1)\sum_{m\sim M}{\alpha}_1(m)\sum_{d_2\sim D_2}{\lambda}(d_1, d_2)\sum_{\substack{mn <X\n\sim N\mn\equiv c_{d_1}\imod {d_1}\mn\equiv c\imod {d_2}}}{\alpha}_2(n)e(mn	heta). \end{align} We apply the Cauchy-Schwarz inequality to obtain  egin{align} 
otag |\mathcal{S}_{	ext{Type II}}|^2\leq &~D_1 (\log X)^{h_1^2-1}\|{\alpha}_1\|_2^2\sum_{\substack{d_1\sim D_1}}\sum_{\substack{m\sim M}} igg|\sum_{\substack{d_2\sim D_2}}{\lambda}(d_1,d_2)\sum_{\substack{n<X/m\ n\sim N\ mn\equiv c_{d_1} \imod {d_1}\mn\equiv c\imod {d_2}}}{\alpha}_2(n)e(mn	heta) igg|^2\ 
otag \ll &~ D_1(\log X)^{h_1^2-1}\|{\alpha}_1\|_2^2\sum_{d_1\sim D_1}\sum_{\substack{d_2, d_2'\sim D_2\(d_2d_2', d_1)=1}}\sum_{\substack{n_1, n_2\sim N\(n_1, d_1d_2)=(n_2, d_1d_2')=1 }} ig|{\alpha}_2(n_1)\overline{{\alpha}_2(n_2)} ig|\ 
otag &	imes \Bigg|\sum_{\substack{m\sim M\m< \min (X/n_1, X/n_2)\mn_1\equiv mn_2\equiv c_{d_1}\imod {d_1}\mn_1\equiv c\imod {d_2}\mn_2\equiv c\imod {d_2'}}}e ig(m(n_1-n_2)	heta ig)\Bigg|\ 
otag \ll &~ D_1(\log X)^{h_1^2-1}\|{\alpha}_1\|_2^2\sum_{d_1\sim D_1}\sum_{\substack{d_2, d_2'\sim D_2\(d_2d_2', d_1)=1}}\sum_{j\in \{1, 2\}}\sum_{\substack{n_1, n_2\sim N\(n_1, d_1d_2)=(n_2, d_1d_2')=1 }} ig|{\alpha}_2(n_j)|^2\ 
otag &	imes \Bigg|\sum_{\substack{m\sim M\m< \min (X/n_1, X/n_2)\mn_1\equiv mn_2\equiv c_{d_1}\imod {d_1}\mn_1\equiv c\imod {d_2}\mn_2\equiv c\imod {d_2'}}}e ig(m(n_1-n_2)	heta ig)\Bigg| \end{align} using the fact $|{\alpha}_2(n_1)\overline{{\alpha}_2(n_2)}|\leq |{\alpha}_2(n_1)|^2 + |{\alpha}_2(n_2)|^2$. The above congruences $mn_1 \equiv mn_2 \equiv c_{d_1} \imod {d_1}$, $mn_1\equiv c \imod {d_2}$, and $mn_1\equiv c\imod {d_2'}$ have a solution in $m$ if and only if $(n_1, d_1d_2)=(n_2, d_1d_2')=1$ and $n_1 \equiv n_2\imod {d_1 (d_2, d_2')}$. Then, we have a unique solution $m\equiv h'\imod {d_1[d_2, d_2']}$ for some $h'\in \{0, 1, \dotsc, d_1[d_2, d_2']-1\} $. Next, we write \[n_1-n_2=n'd_1(d_2, d_2') \quad 	ext{and}\quad m=h'+ m'd_1[d_2, d_2']\] so that $|n'|< 4N/d_1(d_2, d_2')$ and $m'\ll 1+M/d_1[d_2, d_2']$. This implies that  egin{align} 
otag m(n_1-n_2)=h'n'd_1(d_2, d_2') + d_1^2d_2d_2'n'm'. \end{align} Then, we have  egin{align} 
otag \lvert\mathcal{S}_{	extup{Type II}}vert^2 \ll &~D_1(\log X)^{h_1^2-1}\lVert {\alpha}_1Vert_2^2 \sum_{\substack{d_1\sim D_1}}\sum_{\substack{d_2, d_2^\prime \sim D_2\(d_2d_2^\prime, d_1)=1}} \sum_{n_1\sim N}|{\alpha}_2(n_1)|^2\
otag &	imes \sum_{|n^\prime|< 4N/d_1(d_2, d_2^\prime)} igg|\sum_{m^\prime}e(m^\prime n^\prime d_1^2d_2d_2^\prime 	heta) igg|\ 
otag \ll &~D_1(\log X)^{h_1^2-1}\lVert {\alpha}_1Vert_2^2\lVert {\alpha}_2 Vert_2^2\ &	imes \sum_{\substack{d_1\sim D_1}}\sum_{\substack{d_2, d_2^\prime \sim D_2\(d_2d_2^\prime,d_1)=1}}\sum_{|n^\prime|< 4N/d_1(d_2, d_2^\prime)}\min igg(\dfrac{M}{d_1[d_2, d_2^\prime]}+1, \dfrac{1}{\|n^\prime d_1^2d_2d_2^\prime	heta\|} igg). \end{align} The terms with $n^\prime =0$ in \eqref{meth2i} contribute  egin{align} 
